namespace sv_3a4be122390d478f8f5d97952f5700b8.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_3a4be122390d478f8f5d97952f5700b8.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <div class="message-area @(threadOpen ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <div class="area-header">
                <h2># @selectedChannel.Name</h2>
                <p>@selectedChannel.Description</p>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @foreach (var message in messages)
                {
                    <MessageBubble Message="message"
                                   ReplyCount="GetReplyCount(message.Id)"
                                   OnOpenThread="OpenThread"
                                   OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="Message #@selectedChannel.Name"
                          OnSubmit="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Channel? selectedChannel;
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message>? threadReplies;
    private Dictionary<int, int> replyCounts = new();
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;
    private ElementReference messageListRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        await LoadReplyCounts();
        CloseThreadSync();
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll — in a real app, use JS interop to detect scroll-to-top
        // For now this provides the pagination mechanism
    }

    public async Task LoadOlderMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            await LoadReplyCounts();
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var newMsg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(newMsg);
    }

    private async Task OpenThread(Message message)
    {
        threadRootMessage = message;
        threadReplies = await ChatService.GetThreadAsync(message.Id);
        threadOpen = true;
    }

    private void CloseThreadSync()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = null;
    }

    private async Task CloseThread()
    {
        CloseThreadSync();
        await Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies?.Add(reply);

        // Update reply count
        if (replyCounts.ContainsKey(threadRootMessage.Id))
            replyCounts[threadRootMessage.Id]++;
        else
            replyCounts[threadRootMessage.Id] = 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh message list to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messageSkip);
        }
    }

    private int GetReplyCount(int messageId)
    {
        return replyCounts.GetValueOrDefault(messageId, 0);
    }

    private async Task LoadReplyCounts()
    {
        replyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                replyCounts[msg.Id] = thread.Count;
            }
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    position: relative;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background: #34373c;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 8px;
    right: 12px;
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
.message-area {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    transition: width 0.2s ease;
}

.message-area.expanded {
    width: 80%;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

.area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8e9297;
    font-size: 0.85rem;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #8e9297;
    font-size: 1.1rem;
}

/* Message Bubble */
.message-bubble {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 4px;
    position: relative;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

